import{_ as s,l as i,o as e,c as l,v as t,p,x as r,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"备份与 PITR","description":"","frontmatter":{"title":"备份与 PITR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/backup-pitr.md","filePath":"cs/backup-pitr.md","lastUpdated":1789023840000}'),A={name:"cs/backup-pitr.md"};function h(E,a,P,T,_,u){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="备份与-pitr" tabindex="-1">备份与 PITR <a class="header-anchor" href="#备份与-pitr" aria-label="Permalink to &quot;备份与 PITR&quot;">​</a></h1><div class="epigraph"><p>备份是过去某检查点的数据文件像；PITR 再把 WAL 前滚到指定时间。基线与日志链缺一不可。</p><footer>—— 据 Gray and Reuter 备份；PostgreSQL PITR；物理备份实践</footer></div><p><a href="/cs/rto-recovery">上一课</a>谈崩溃重启。本课谈<strong>介质失败与误删除</strong>：ARIES 救不了删掉的文件或逻辑错误（drop table）。备份+时间点恢复（PITR）用基线副本+连续 WAL 归档。逻辑复制下一课是另一条传送变化的路。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物理备份：拷数据文件（常模糊一致+WAL 补齐）或快照。逻辑备份：dump SQL，慢、粒度表，可跨版本。PITR：从基线前滚 WAL 到时间 T 或某 LSN/事务。缺口是<strong>归档完整性</strong>：WAL 缺口则只能回到缺口前。误操作恢复要停在错误前，RPO 取决于归档粒度。</p><p>备份本身要测恢复，否则只是占用对象存储。与 TDE：备份密文，恢复要密钥。</p><p><span class="marginnote">Postgres <code>recovery_target_time</code>。热备份 vs 冷备份。本课不背某云快照 API。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>全量+增量（变化页）+ WAL。保留窗口：能 PITR 多远。校验：备份后 checksum、定期试恢复到临时实例。应用：恢复后可能要处理序列、复制槽、连接密码。</p><p>与组提交：归档的是已持久日志。异步提交未进归档的会丢，与 D 等级一致。</p>',10)),(e(),p(c,null,{default:r(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E6%95%B0%E6%8D%AE%E5%83%8F%22%5D%20--%3E%20ROLL%5B%22%E5%BA%94%E7%94%A8%E5%BD%92%E6%A1%A3%20WAL%22%5D%0A%20%20ROLL%20--%3E%20T%5B%22%E5%81%9C%E5%9C%A8%E6%97%B6%E9%97%B4%20T%22%5D%0A%20%20GAP%5B%22WAL%20%E7%BC%BA%E5%8F%A3%22%5D%20--%3E%20STOP%5B%22%E5%8F%AA%E8%83%BD%E5%9B%9E%E5%88%B0%E7%BC%BA%E5%8F%A3%E5%89%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模糊备份：拷文件时页在变，必须靠同时段 WAL redo 修到一致——与模糊检查点同构。快照若原子则少修。逻辑 dump 无 PITR 细粒度，除非再叠逻辑日志。</p><p>膨胀：未 vacuum 的堆会把死元组拷进备份，体积与恢复时间都差。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 CDC 解析。也不把备份当只读副本（延迟与用途不同）。Jepsen 后课测的是运行时一致，不是备份链。</p><p>后课默认：介质与误操作靠备份+PITR；崩溃靠 ARIES。逻辑复制与 CDC：把行变化流给下游，不是整库前滚。</p><p>没有演练的 PITR 目标时间是愿望。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>物理基线+WAL 链做 PITR；缺口打断链。</li><li>备份要试恢复；密文备份依赖密钥。</li><li>逻辑复制与 CDC 下一课。</li><li>出处：Gray and Reuter；PostgreSQL PITR。</li></ul>',9))])}const R=s(A,[["render",h]]);export{B as __pageData,R as default};
